def iter_best_Ts_ge_(emay_prime_factors4T_or_factor_pint, prev_max_S, min_T, may_max_T=None, /):
    '(...|ps4T/[prime]|(T/pint->p2e4T/{prime:exp})) -> prev_max_S/int -> min_T/pint -> Iter (T, p2e4T, S, q2e4S) # [prev_max_S:=if min_T == 1 then -1 else max{S{t} | [t:<-[1..<min_T]]}][1 <= T <= min_T][@[t:<-[1..<T]] -> [S{t} < S{T}]] # [@[s::int{>=1}] -> [[@[i::int] -> [gcd(i,s) == 1] -> [i**T =[%s]= 1]] <-> [S%s == 0]]] # [p2e4T==the_prime_factorization_of_(T)][q2e4S==the_prime_factorization_of_(S)]'
    check_int_ge(1, min_T)
    check_int_ge(-1, prev_max_S)
    if min_T == 1:
        if not prev_max_S == -1:raise TypeError
    else:
        check_int_ge(2, prev_max_S)

    factor_pint_ = factor_pint5or_emay_prime_factors4target_pint_(emay_prime_factors4T_or_factor_pint)
    Ts = count(min_T) if None is may_max_T else range(min_T, 1+may_max_T)
    try:
        for T in Ts:
            if T&1 and T > 1:continue
            (_T, p2e4T, S, q2e4S) = max_S_ex5T_(factor_pint_, T)
            if S > prev_max_S:
                yield (T, p2e4T, S, q2e4S)
                (prev_max_S, min_T) = S, 1+T
            else:
                min_T = 1+T
    except (Exception, KeyboardInterrupt, BrokenPipeError) as exc:
        raise Exception(exc, prev_max_S, min_T)

